import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $ = (s) => document.querySelector(s);
const canvas = $('#game');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a6c1b2');
scene.fog = new THREE.Fog('#a6c1b2', 75, 190);
const camera = new THREE.PerspectiveCamera(54, 1, .1, 260);
scene.add(new THREE.HemisphereLight('#e9f2d9', '#59645a', 2.0));
const sun = new THREE.DirectionalLight('#fff0ce', 3.2);
sun.position.set(-38, 65, 26); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -80; sun.shadow.camera.right = 80; sun.shadow.camera.top = 80; sun.shadow.camera.bottom = -80;
scene.add(sun);
const mat = (color, roughness=.8, metalness=0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const grassMat=mat('#859876'), asphaltMat=mat('#515956'), lineMat=mat('#e4d7a9'), darkMat=mat('#242b2a'), rubberMat=mat('#171b1b'), windowMat=mat('#9ab7b2',.22,.25), creamMat=mat('#e9dfc4'), orangeMat=mat('#f2a64c');
const world = new THREE.Group(); scene.add(world);
const floor = new THREE.Mesh(new THREE.PlaneGeometry(260,260), grassMat); floor.rotation.x=-Math.PI/2; floor.position.y=-.12; floor.receiveShadow=true; world.add(floor);
function disk(radius, color, y=-.07, segments=96) { const m=new THREE.Mesh(new THREE.CircleGeometry(radius,segments),mat(color));m.rotation.x=-Math.PI/2;m.position.y=y;m.receiveShadow=true;world.add(m);return m; }
disk(77,'#545a54',-.08); disk(70,'#697061',-.06);
// Asphalt loop and its very official lane markings.
const road=new THREE.Mesh(new THREE.RingGeometry(40,61,96),asphaltMat); road.rotation.x=-Math.PI/2;road.position.y=.01;road.receiveShadow=true;world.add(road);
for (const r of [40.7,60.3]) { const ring=new THREE.Mesh(new THREE.TorusGeometry(r,.16,5,120),lineMat);ring.rotation.x=Math.PI/2;ring.position.y=.08;world.add(ring); }
const zoneRing=new THREE.Mesh(new THREE.TorusGeometry(77,.45,8,160),new THREE.MeshBasicMaterial({color:'#e47c53'}));zoneRing.rotation.x=Math.PI/2;zoneRing.position.y=.18;world.add(zoneRing);
// Scatter a few lanes of civic infrastructure around the arena.
function box(parent, size, color, pos, rotation=0, material=null) {const o=new THREE.Mesh(new THREE.BoxGeometry(...size),material||mat(color));o.position.set(...pos);o.rotation.y=rotation;o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function cylinder(parent, rt, rb, h, color, pos, seg=8) {const o=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,seg),mat(color));o.position.set(...pos);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
const rand=(a,b)=>a+Math.random()*(b-a);
for(let i=0;i<26;i++){
 const a=i/26*Math.PI*2, r=rand(64,92), x=Math.cos(a)*r,z=Math.sin(a)*r;
 if(i%3===0){const h=rand(3,8),w=rand(3,7),d=rand(3,6);box(world,[w,h,d],['#bcad8f','#b5a68d','#d1bea0'][i%3],[x,h/2-.05,z],rand(-.4,.4));box(world,[w*.72,.12,.1],'#384744',[x,h*.65,z+d/2+.06]);}
 else {cylinder(world,.12,.24,1.3,'#55483b',[x,.62,z]);const crown=new THREE.Mesh(new THREE.ConeGeometry(rand(1.2,2),rand(2,3.8),7),mat(i%2?'#526e52':'#607955'));crown.position.set(x,2.4,z);crown.castShadow=true;world.add(crown);}
}
// County fair props: inexplicably expensive monuments and abandoned snack stands.
for(let i=0;i<8;i++){const a=i/8*Math.PI*2,x=Math.cos(a)*31,z=Math.sin(a)*31;const stand=new THREE.Group();stand.position.set(x,0,z);stand.rotation.y=-a;world.add(stand);box(stand,[5,2.4,3],i%2?'#c16f54':'#d0b779',[0,1.2,0]);box(stand,[5.2,.3,3.2],'#334743',[0,2.5,0]);box(stand,[2.1,1,.08],'#eee0b6',[0,1.2,1.55]);}
for(let i=0;i<22;i++){const x=rand(-75,75),z=rand(-75,75);if(Math.hypot(x,z)<24|| (Math.hypot(x,z)>39&&Math.hypot(x,z)<62))continue;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(rand(.35,1.1),0),mat(i%2?'#786f5e':'#8c826d'));rock.position.set(x,.35,z);rock.scale.y=.65;rock.castShadow=true;world.add(rock);}
const drivers=[
 {name:'Donna Doomscroll',tag:'THE COMMENTATOR',icon:'📱',color:'#ed7b58',accent:'#f5d17c',speed:1.04,armor:1,fire:1,special:'HOT TAKE',bio:'A wellness influencer with a <strong>very unhealthy</strong> relationship to other people’s opinions. Her boost leaves a trail of sponsored regret.'},
 {name:'Sheriff Coupon',tag:'THE LAW-ish',icon:'🤠',color:'#789b71',accent:'#e5d6a5',speed:.91,armor:1.42,fire:.96,special:'PAPERWORK',bio:'He has deputized himself and will absolutely write you a ticket during a high-speed chase. <strong>Extra sturdy.</strong> Emotionally? Unclear.'},
 {name:'Dr. Hotdog',tag:'THE PROFESSIONAL',icon:'🌭',color:'#d99a43',accent:'#f5eee0',speed:.98,armor:.92,fire:1.42,special:'MEAT SWEATS',bio:'A licensed doctor of vibes and an unlicensed surgeon of the open road. Fires faster. Please do not ask about the mustard.'}
];
let selected=0,previewCar=null,gameState='menu',player=null,actors=[],projectiles=[],pickups=[],particles=[],keys={},last=performance.now(),gameTime=0,zoneTime=105,zoneRadius=77,kills=0,toastUntil=0,fireClock=0,specialClock=0,spawnClock=0,soundOn=true,audioCtx=null;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function makeCar(driver, isPlayer=false){
 const root=new THREE.Group(); const shell=new THREE.Group();root.add(shell);
 const bodyMat=mat(driver.color,.48,.12),accent=mat(driver.accent,.55,.08);
 box(shell,[2.15,.66,3.35],driver.color,[0,.82,0],0,bodyMat);
 box(shell,[1.55,.72,1.62],driver.color,[0,1.43,-.12],0,bodyMat);
 box(shell,[1.48,.5,.1],'#263b3d',[0,1.47,.72],0,windowMat);
 box(shell,[1.35,.48,.1],'#314748',[0,1.45,-.91],0,windowMat);
 box(shell,[.18,.2,.08],'#fff0c8',[-.78,.86,-1.69]);box(shell,[.18,.2,.08],'#fff0c8',[.78,.86,-1.69]);
 box(shell,[.3,.19,.09],'#db5442',[-.74,.84,1.69]);box(shell,[.3,.19,.09],'#db5442',[.74,.84,1.69]);
 box(shell,[1.4,.1,.22],driver.accent,[0,1.03,-1.55],0,accent);
 // Four chunky wheels with hubcaps.
 for(const x of [-1.12,1.12])for(const z of [-1.05,1.05]){const tire=new THREE.Mesh(new THREE.CylinderGeometry(.43,.43,.28,12),rubberMat);tire.rotation.z=Math.PI/2;tire.position.set(x,.48,z);tire.castShadow=true;shell.add(tire);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.19,.19,.3,10),accent);hub.rotation.z=Math.PI/2;hub.position.set(x,.48,z);shell.add(hub);}
 // Distinctly daft roof accessories and a billboard-sized driver face.
 if(driver===drivers[0]){const phone=box(shell,[.36,.62,.12],'#202a2d',[.05,2.12,-.1]);box(shell,[.23,.37,.025],'#77b6c1',[.05,2.13,-.025]);}
 if(driver===drivers[1]){cylinder(shell,.3,.3,.17,'#e1cf9e',[0,1.94,-.08],8);const siren=new THREE.Mesh(new THREE.SphereGeometry(.22,8,6),mat('#e35a43'));siren.position.set(0,2.12,-.08);shell.add(siren);}
 if(driver===drivers[2]){cylinder(shell,.18,.13,.8,'#e7e0ca',[0,2.08,-.08],10);cylinder(shell,.22,.21,.08,'#d94f38',[0,2.46,-.08],10);}
 const face=new THREE.Group();face.position.set(0,1.45,-1.52);shell.add(face);
 const skin=mat(isPlayer?'#efc59b':'#d8ab85');const head=new THREE.Mesh(new THREE.SphereGeometry(.36,12,9),skin);head.scale.set(1,.82,.5);face.add(head);
 const eyeMat=mat('#262727');for(const x of [-.13,.13]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.035,6,5),eyeMat);eye.position.set(x,.03,-.17);face.add(eye);}
 // Bumper ram and little exhaust puffs.
 box(shell,[1.9,.18,.24],'#9c9b86',[0,.47,-1.79]);box(shell,[.18,.18,.4],'#303536',[-.68,.37,1.7]);box(shell,[.18,.18,.4],'#303536',[.68,.37,1.7]);
 root.userData={shell,driver};root.scale.setScalar(isPlayer?1.05:1);return root;
}
function setPreview(){if(previewCar)scene.remove(previewCar);previewCar=makeCar(drivers[selected],true);previewCar.position.set(0,0,7);previewCar.rotation.y=-.38;scene.add(previewCar);}
setPreview();

const driversNode=$('#drivers');
drivers.forEach((d,i)=>{const b=document.createElement('button');b.className='driver-card'+(i===0?' active':'');b.innerHTML=`<span class="driver-icon">${d.icon}</span><strong>${d.name}</strong><small>${d.tag}</small>`;b.addEventListener('click',()=>selectDriver(i));driversNode.append(b);});
function selectDriver(i){selected=i;[...driversNode.children].forEach((el,n)=>el.classList.toggle('active',n===i));$('.panel-kicker span').textContent=`0${i+1} / 03`;$('#bio').innerHTML=drivers[i].bio;$('#ability-name').textContent=drivers[i].special;setPreview();}
selectDriver(0);
function addToast(text,duration=2100){const t=$('#toast');t.textContent=text;t.style.opacity='1';toastUntil=performance.now()+duration;}
function actor(driver,index,x,z,isPlayer=false){const car=makeCar(driver,isPlayer);car.position.set(x,0,z);scene.add(car);const o={mesh:car,driver,index,isPlayer,hp:100*driver.armor,maxHp:100*driver.armor,heading:Math.atan2(-x,z),speed:0,boost:100,dead:false,ai:Math.random()*2,fire:Math.random(),special:0};if(isPlayer)player=o;actors.push(o);return o;}
function startGame(){
 if(previewCar){scene.remove(previewCar);previewCar=null;}$('#title-screen').classList.add('hidden');$('#end-screen').classList.add('hidden');$('#hud').classList.remove('hidden');if('ontouchstart'in window)$('#touch-controls').classList.remove('hidden');
 projectiles.forEach(p=>scene.remove(p.mesh));projectiles=[];actors.forEach(a=>scene.remove(a.mesh));actors=[];pickups.forEach(p=>scene.remove(p.mesh));pickups=[];particles.forEach(p=>scene.remove(p.mesh));particles=[];kills=0;gameTime=0;zoneTime=105;zoneRadius=77;fireClock=0;specialClock=0;spawnClock=18;$('#kill-count').textContent='00';
 const r=rand(2,7);actor(drivers[selected],0,0,r,true);
 for(let i=0;i<7;i++){const a=i/7*Math.PI*2+rand(-.18,.18),dist=rand(30,53);actor(drivers[(selected+i+1)%3],i+1,Math.cos(a)*dist,Math.sin(a)*dist);}
 camera.position.set(0,11,19);camera.lookAt(0,0,0);$('#ability-name').textContent=drivers[selected].special;addToast('THE COUNTY HAS DECLARED THIS A SPORT.',2600);gameState='playing';
}
$('#start-button').addEventListener('click',startGame);$('#again-button').addEventListener('click',()=>{gameState='menu';$('#end-screen').classList.add('hidden');$('#hud').classList.add('hidden');$('#title-screen').classList.remove('hidden');selectDriver(selected);});
function endGame(won){if(gameState!=='playing')return;gameState='ended';$('#end-screen').classList.remove('hidden');$('#end-eyebrow').textContent=won?'UNOFFICIAL COUNTY CHAMPION':'PUBLIC SAFETY ANNOUNCEMENT';$('#end-title').innerHTML=won?'YOU ARE<br><em>THE PROBLEM.</em>':'PLEASE REMAIN<br><em>IN YOUR VEHICLE.</em>';
 $('#end-copy').textContent=won?'Congratulations. The county has awarded you a ceremonial cone and a strongly worded pamphlet.':'Your vehicle has been reassigned to the county. Your parking tickets remain your responsibility.';$('#result-kills').textContent=kills;$('#result-time').textContent=clock(gameTime);}
function clock(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;}
function playTone(freq=180,duration=.08){if(!soundOn)return;try{audioCtx ||= new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='triangle';o.frequency.value=freq;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
$('#sound-toggle').addEventListener('click',()=>{soundOn=!soundOn;$('#sound-toggle').textContent=soundOn?'♪ SOUND ON':'♪ SOUND OFF';});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='e'&&gameState==='playing')useSpecial();if(k==='escape'&&gameState==='playing'){gameState='paused';addToast('PAUSED. LIKE A RESPONSIBLE ADULT.',99999);}});
window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;if(e.key==='Escape'&&gameState==='paused'){gameState='playing';$('#toast').style.opacity='0';}});
window.addEventListener('blur',()=>{keys={};});
canvas.addEventListener('pointerdown',()=>{keys.mouse=true;});window.addEventListener('pointerup',()=>{keys.mouse=false;});
for(const btn of document.querySelectorAll('.touch-controls button')){const key=btn.dataset.key;const on=e=>{e.preventDefault();keys[key]=true;if(key==='e')useSpecial();};const off=e=>{e.preventDefault();keys[key]=false;};btn.addEventListener('pointerdown',on);btn.addEventListener('pointerup',off);btn.addEventListener('pointercancel',off);btn.addEventListener('pointerleave',off);}
function useSpecial(){if(!player||gameState!=='playing'||specialClock>0)return;const d=player.driver;
 if(d===drivers[0]){specialClock=13;for(const a of actors){if(a!==player&&!a.dead&&a.mesh.position.distanceTo(player.mesh.position)<14){damage(a,24,player);}}addToast('HOT TAKE DEPLOYED. EVERYONE IS WRONG.');playTone(540,.2);}
 else if(d===drivers[1]){specialClock=15;player.hp=Math.min(player.maxHp,player.hp+32);player.boost=Math.min(100,player.boost+35);addToast('PAPERWORK FILED. DAMAGE DENIED.');playTone(410,.2);}
 else{specialClock=14;for(let i=0;i<12;i++){const a=player.heading+(i-5.5)*.11;shoot(player,a,1.3);}addToast('MEAT SWEATS: MUSTARD AT SPEED.');playTone(300,.2);}
}
function shoot(owner,heading,power=1){const d=owner.driver;const mesh=new THREE.Mesh(new THREE.SphereGeometry(.22,8,7),new THREE.MeshBasicMaterial({color:d.accent}));const p=owner.mesh.position;mesh.position.set(p.x+Math.sin(heading)*2,p.y+1.05,p.z-Math.cos(heading)*2);scene.add(mesh);projectiles.push({mesh,owner,heading,speed:30*power,life:2.6,damage:16*d.fire*power});if(owner.isPlayer)playTone(210,.055);}
function damage(target,amount,source){if(target.dead)return;target.hp-=amount;if(target.isPlayer){$('#damage-flash').style.background='rgba(232,70,43,.27)';setTimeout(()=>$('#damage-flash').style.background='rgba(232,70,43,0)',90);}
 if(target.hp<=0){target.dead=true;scene.remove(target.mesh);burst(target.mesh.position,target.driver.color,18);if(source?.isPlayer){kills++;$('#kill-count').textContent=String(kills).padStart(2,'0');addToast(['THAT WAS DEFINITELY SELF DEFENSE.','COUNTY COUNSEL HAS LEFT THE CHAT.','YOU WIN THE ARGUMENT. TECHNICALLY.'][kills%3]);if(Math.random()<.54)spawnPickup(target.mesh.position.x,target.mesh.position.z);}if(target.isPlayer)endGame(false);if(actors.filter(a=>!a.dead).length===1)endGame(true);}
}
function burst(pos,color,count=9){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.BoxGeometry(.12,.12,.12),new THREE.MeshBasicMaterial({color}));mesh.position.copy(pos);mesh.position.y+=.8;scene.add(mesh);particles.push({mesh,vel:new THREE.Vector3(rand(-5,5),rand(1,8),rand(-5,5)),life:rand(.35,.8)});}}
function spawnPickup(x=rand(-54,54),z=rand(-54,54)){const group=new THREE.Group();const ring=new THREE.Mesh(new THREE.TorusGeometry(.7,.12,6,12),orangeMat);ring.rotation.x=Math.PI/2;group.add(ring);const cross=box(group,[.18,.85,.18],'#eef0d5',[0,.2,0]);box(group,[.65,.18,.18],'#eef0d5',[0,.2,0]);group.position.set(x,.85,z);scene.add(group);pickups.push({mesh:group,life:20});}
function updatePlayer(dt){if(!player||player.dead)return;const a=player;const k=(name)=>!!keys[name];const forward=(k('w')||k('arrowup'))?1:0,reverse=(k('s')||k('arrowdown'))?1:0,steer=(k('d')||k('arrowright')?1:0)-(k('a')||k('arrowleft')?1:0);
 const boosting=(k('shift')||k('shiftleft')||k('shift'))&&a.boost>0&&forward;const accel=(forward?20:reverse?-13:0)*(boosting?1.55:1)*a.driver.speed;a.speed+=accel*dt;a.speed*=Math.pow(forward||reverse?.985:.91,dt*60);a.speed=clamp(a.speed,-10,boosting?31:23);if(boosting)a.boost=Math.max(0,a.boost-26*dt);else a.boost=Math.min(100,a.boost+10*dt);
 a.heading+=steer*dt*(.85+Math.min(Math.abs(a.speed)/14,1.5))*(a.speed<0?-1:1);a.mesh.rotation.y=a.heading;
 a.mesh.position.x+=Math.sin(a.heading)*a.speed*dt;a.mesh.position.z-=Math.cos(a.heading)*a.speed*dt;
 const dist=Math.hypot(a.mesh.position.x,a.mesh.position.z);if(dist>zoneRadius-2){a.speed*=.96; if(dist>zoneRadius+1){a.hp-=9*dt;$('#zone-status').style.color='#fd8b6a';if(Math.random()<.035)addToast('OUTSIDE THE COUNTY LINE. BAD IDEA.');}}
 for(const other of actors){if(other===a||other.dead)continue;const dx=a.mesh.position.x-other.mesh.position.x,dz=a.mesh.position.z-other.mesh.position.z,dd=Math.hypot(dx,dz);if(dd<2.8){a.speed*=.94;other.speed*=.94;const dmg=4*dt;damage(a,dmg,other);damage(other,dmg,a);}}
 if((k(' ')||k('mouse'))&&fireClock<=0){shoot(a,a.heading);fireClock=.34/a.driver.fire;}
 $('#health-value').textContent=Math.max(0,Math.ceil(a.hp/a.maxHp*100));$('#health-fill').style.width=`${clamp(a.hp/a.maxHp*100,0,100)}%`;$('#boost-fill').style.width=`${a.boost}%`;$('#speed-value').textContent=String(Math.round(Math.abs(a.speed)*4.1)).padStart(3,'0');$('#ability-box').style.opacity=specialClock>0?'.6':'1';$('#ability-box small').textContent=specialClock>0?`READY IN ${specialClock.toFixed(1)}s`:'E TO DEPLOY';
}

function updateBots(dt){for(const a of actors){if(a.isPlayer||a.dead)continue;a.ai-=dt;a.fire-=dt;
 const p=player?.mesh.position||new THREE.Vector3();const pos=a.mesh.position;let targetX=p.x,targetZ=p.z;
 // A bot occasionally chooses a less direct route, as the county-approved training manual recommends.
 const distToPlayer=Math.hypot(targetX-pos.x,targetZ-pos.z);if(a.ai<=0){a.ai=rand(1.3,3.8);a.wander=rand(-1,1);}
 if(Math.hypot(pos.x,pos.z)>zoneRadius-9){targetX=-pos.x*.7;targetZ=-pos.z*.7;}
 const desired=Math.atan2(targetX-pos.x,-(targetZ-pos.z));let delta=((desired-a.heading+Math.PI*3)%(Math.PI*2))-Math.PI;
 a.heading+=clamp(delta,-1.7*dt,1.7*dt)+(a.wander||0)*dt*.21;a.speed+=(16*a.driver.speed-a.speed)*Math.min(1,dt*1.1);a.speed=Math.min(a.speed,17*a.driver.speed);
 a.mesh.rotation.y=a.heading;pos.x+=Math.sin(a.heading)*a.speed*dt;pos.z-=Math.cos(a.heading)*a.speed*dt;
 const aim=Math.atan2(p.x-pos.x,-(p.z-pos.z)),aimDiff=Math.abs(((aim-a.heading+Math.PI*3)%(Math.PI*2))-Math.PI);
 if(distToPlayer<39&&aimDiff<.65&&a.fire<=0&&player&&!player.dead){shoot(a,a.heading+rand(-.08,.08));a.fire=rand(.8,1.35)/a.driver.fire;}
 for(const b of actors){if(b===a||b.dead)continue;const d=a.mesh.position.distanceTo(b.mesh.position);if(d<2.5){a.speed*=.96;b.speed*=.97;}}
 const radius=Math.hypot(pos.x,pos.z);if(radius>zoneRadius-1){a.hp-=dt*(radius>zoneRadius+4?8:3);if(a.hp<=0)damage(a,a.hp+1,null);}
 }}
function updateProjectiles(dt){for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.life-=dt;p.mesh.position.x+=Math.sin(p.heading)*p.speed*dt;p.mesh.position.z-=Math.cos(p.heading)*p.speed*dt;
 let hit=null;for(const a of actors){if(a===p.owner||a.dead)continue;if(p.mesh.position.distanceTo(new THREE.Vector3(a.mesh.position.x,a.mesh.position.y+1,a.mesh.position.z))<1.6){hit=a;break;}}
 if(hit){damage(hit,p.damage,p.owner);burst(p.mesh.position,p.owner.driver.accent,4);p.life=0;}
 if(p.life<=0){scene.remove(p.mesh);projectiles.splice(i,1);}
 }}
function updatePickups(dt){for(let i=pickups.length-1;i>=0;i--){const p=pickups[i];p.life-=dt;p.mesh.rotation.y+=dt*1.8;p.mesh.position.y=.85+Math.sin(gameTime*3+i)*.15;if(player&&!player.dead&&player.mesh.position.distanceTo(p.mesh.position)<2.2){player.hp=Math.min(player.maxHp,player.hp+30);player.boost=Math.min(100,player.boost+35);addToast('COUNTY-ISSUED FIRST AID. PROBABLY EXPIRED.');playTone(620,.14);p.life=0;}if(p.life<=0){scene.remove(p.mesh);pickups.splice(i,1);}}}
function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.vel.y-=11*dt;p.mesh.position.addScaledVector(p.vel,dt);p.mesh.rotation.x+=dt*4;if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1);}}}
